# Strict validation: Check that no word in the list is formed by taking another word in the list and simply appending 'S'
words_set = set()
clean_ch19 = []

for word, definition, example in raw_pets_words:
    w = word.upper().strip().replace("-", "").replace(" ", "")
    if w in used_words:
        continue
    if w in words_set:
        continue
    if w.endswith('S') and w[:-1] in words_set:
        print(f"Skipping plural duplicate: {w} (base {w[:-1]} already present)")
        continue
    words_set.add(w)
    clean_ch19.append({
        "word": w,
        "definition": definition,
        "example": example
    })

print(f"Total raw words prepared: {len(raw_pets_words)}")
print(f"Total valid unique Ch19 words: {len(clean_ch19)}")

assert len(clean_ch19) >= 364, f"Need at least 364 words, got {len(clean_ch19)}"

with open("scratch/chapter_19_clean_words.json", "w", encoding="utf-8") as f:
    json.dump(clean_ch19, f, indent=2)

print("Successfully generated scratch/chapter_19_clean_words.json!")
